module line_counter (
input wire clk,
input wire reset,
input wire advance,
output reg [13:0] line_count
);
always @(posedge clk) begin
if (reset)
line_count <= 14'h0000;
else if (advance)
line_count <= line_count + 1'b1; // wrap at 0x3fff + 1 -> 0x0000
end
